import heapq
class Solution:
    def minSelection(self, availableIntervals: list[list[int]], targetIntervals: list[list[int]]) -> int:
        targets = sorted(targetIntervals); merged = []
        for start, end in targets:
            if merged and start <= merged[-1][1]: merged[-1][1] = max(merged[-1][1], end)
            else: merged.append([start, end])
        available = sorted(availableIntervals); i = count = 0; reach = -1; heap = []
        for start, end in merged:
            if reach < start: reach = start - 1
            while reach < end:
                point = start if reach < start else reach
                while i < len(available) and available[i][0] <= point:
                    heapq.heappush(heap, -available[i][1]); i += 1
                while heap and -heap[0] < point: heapq.heappop(heap)
                if not heap: return -1
                next_reach = -heapq.heappop(heap)
                if next_reach == point and point < end: return -1
                reach = next_reach; count += 1
        return count
